#include <vector>
#include <unordered_set>
#include <numeric>

class Solution {
    bool check(const std::vector<std::vector<int>>& g, long long s) {
        long long top = 0;
        std::unordered_set<int> seen;
        int m = g.size(), n = g[0].size();
        for (int i = 0; i < m; ++i) {
            for (int val : g[i]) {
                top += val;
                seen.insert(val);
            }
            long long bot = s - top;
            if (top - bot == 0 || top - bot == g[0][0] || top - bot == g[0][n - 1] || top - bot == g[i][0]) {
                return true;
            }
            if (n > 1 && i > 0 && seen.count(top - bot)) {
                return true;
            }
        }
        return false;
    }

public:
    bool canPartitionGrid(std::vector<std::vector<int>>& grid) {
        long long total = 0;
        for (const auto& r : grid) {
            for (int val : r) total += val;
        }

        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> revGrid = grid;
        std::reverse(revGrid.begin(), revGrid.end());

        std::vector<std::vector<int>> trans(n, std::vector<int>(m));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                trans[j][i] = grid[i][j];
            }
        }

        std::vector<std::vector<int>> revTrans = trans;
        std::reverse(revTrans.begin(), revTrans.end());

        return check(grid, total) || check(revGrid, total) || check(revTrans, total) || check(trans, total);
    }
};

import java.util.*;

class Solution {
    private boolean check(int[][] g, long s) {
        long top = 0;
        Set<Integer> seen = new HashSet<>();
        int m = g.length, n = g[0].length;
        for (int i = 0; i < m; ++i) {
            for (int val : g[i]) {
                top += val;
                seen.add(val);
            }
            long bot = s - top;
            if (top - bot == 0 || top - bot == g[0][0] || top - bot == g[0][n - 1] || top - bot == g[i][0]) {
                return true;
            }
            if (n > 1 && i > 0 && seen.contains((int)(top - bot))) {
                return true;
            }
        }
        return false;
    }

    public boolean canPartitionGrid(int[][] grid) {
        long total = 0;
        for (int[] r : grid) {
            for (int val : r) total += val;
        }

        int m = grid.length, n = grid[0].length;
        int[][] revGrid = new int[m][n];
        for (int i = 0; i < m; ++i) revGrid[i] = grid[m - 1 - i];

        int[][] trans = new int[n][m];
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                trans[j][i] = grid[i][j];
            }
        }

        int[][] revTrans = new int[n][m];
        for (int i = 0; i < n; ++i) revTrans[i] = trans[n - 1 - i];

        return check(grid, total) || check(revGrid, total) || check(revTrans, total) || check(trans, total);
    }
}

