var canPartitionGrid = function(grid) {
    let total = 0;
    for (const r of grid) {
        for (const val of r) total += val;
    }

    function check(g, s) {
        let top = 0;
        const seen = new Set();
        const m = g.length, n = g[0].length;
        for (let i = 0; i < m; ++i) {
            for (const val of g[i]) {
                top += val;
                seen.add(val);
            }
            const bot = s - top;
            if (top - bot === 0 || top - bot === g[0][0] || top - bot === g[0][n - 1] || top - bot === g[i][0]) {
                return true;
            }
            if (n > 1 && i > 0 && seen.has(top - bot)) {
                return true;
            }
        }
        return false;
    }

    const m = grid.length, n = grid[0].length;
    const revGrid = [...grid].reverse();
    const trans = Array.from({ length: n }, (_, j) => Array.from({ length: m }, (_, i) => grid[i][j]));
    const revTrans = [...trans].reverse();

    return check(grid, total) || check(revGrid, total) || check(revTrans, total) || check(trans, total);
};
